solution:
def step(state, action):
    e=state['elixir']
    if action=='wait':
        e=min(10,e+1)
    elif action=='xbow' and e>=6:
        e-=6
    else:
        raise ValueError('action is unavailable')
    return {'elixir':e,'tick':state['tick']+1}

