import json
from pathlib import Path

def count_outcomes(rows):
    counts={b:0 for b in ('WIN','LOSS','DRAW','unknown')}
    for row in rows:
        v=row.get('derived')
        counts[v if v in ('WIN','LOSS','DRAW') else 'unknown']+=1
    return counts
rows=[json.loads(s) for s in Path('scratchpad/gauntlet/L74/loss_review/matches.jsonl').read_text(encoding='utf-8').splitlines() if s.strip()]
counts=count_outcomes(rows)
